WITH department_totals AS (SELECT dept_id, SUM(CASE WHEN level = 'L2' THEN salary ELSE 0 END) AS l2_salary, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values FROM employees GROUP BY dept_id) SELECT d.id, d.budget, d.location, dt.l2_salary, dt.job_title_values FROM departments d JOIN department_totals dt ON d.id = dt.dept_id ORDER BY budget DESC
